<template>
  <section class="radar-page ml-stagger">
    <header class="radar-header"><div><p class="eyebrow">FRESHNESS RADAR / 02</p><h1>时效雷达</h1><p class="subtitle">持续检查已登记来源，新增或变更内容只生成待审候选，人工采纳后才发布。</p></div><RouterLink class="research-link" to="/web-research">进入联网检索 <span>↗</span></RouterLink></header>

    <section class="radar-overview"><article><span>监测来源</span><b>{{ sources.length }}</b><small>已登记</small></article><article><span>自动检测</span><b>{{ monitoringCount }}</b><small>后台按计划运行</small></article><article><span>发现变更</span><b>{{ changedCount }}</b><small>新增或更新快照</small></article><article class="radar-state"><span>调度状态</span><b>{{ monitoringCount ? 'ACTIVE' : 'MANUAL' }}</b><small>到期来源串行检查</small></article></section>

    <section class="source-registration"><div class="section-heading"><div><p class="eyebrow">SOURCE REGISTRY</p><h2>登记检测来源</h2></div><span>同域采集 · 最多 50 页 · 深度 0–2</span></div>
      <form @submit.prevent="createSource"><label class="name-field"><span>来源名称</span><input v-model="form.name" maxlength="120" placeholder="例如：项目官方文档" required /></label><label class="library-field"><span>关联知识库</span><select v-model="form.libraryId" required><option value="" disabled>选择个人知识库</option><option v-for="library in libraries" :key="library.id" :value="library.id">{{ library.name }}</option></select></label><label class="url-field"><span>公开起始网址</span><input v-model="form.seedUrl" type="url" placeholder="https://docs.example.com/guide" required /></label><label class="number-field"><span>页数</span><input v-model.number="form.maxPages" type="number" min="1" max="50" required /></label><label class="number-field"><span>深度</span><input v-model.number="form.depth" type="number" min="0" max="2" required /></label><button class="primary-action" type="submit" :disabled="creating || !libraries.length">{{ creating ? '登记中…' : '登记来源' }}</button></form>
      <p v-if="!libraries.length" class="library-empty">还没有可用个人知识库，请先到 <RouterLink to="/knowledge/personal">我的知识库</RouterLink> 创建。</p>
    </section>
    <p v-if="error" class="message error" role="alert">{{ error }}</p><div v-if="notice" class="message notice" role="status"><span>{{ notice }}</span><RouterLink v-if="notice.includes('待审')" to="/knowledge/review">前往知识审核 ↗</RouterLink></div>

    <RelationGraph :nodes="graph.nodes" :edges="graph.edges" :active-id="activeId" :scanning="checkingId !== null" aria-label="时效雷达来源关系网状动态图" @select="selectGraphNode" />

    <div class="radar-layout">
      <main><div class="section-heading"><div><p class="eyebrow">WATCH SOURCES</p><h2>来源状态</h2></div><button class="text-button" type="button" @click="loadSources">刷新状态</button></div>
        <div v-if="sources.length" class="source-list"><article v-for="source in sources" :key="source.id" class="source-row" :class="{ selected: selectedId === source.id, failed: source.lastStatus === 'FAILED' }">
          <button class="source-select" type="button" @click="selectSource(source)"><span class="source-status" :class="statusClass(source)">{{ source.lastStatus || 'WAITING' }}</span><h3>{{ source.name }}</h3><p>{{ host(source.seedUrl) }}</p><small>{{ source.maxPages }} 页上限 · 深度 {{ source.depth }} · 上次 {{ formatTime(source.lastRunAt) }}</small></button>
          <div class="source-controls"><label class="monitor-toggle"><input type="checkbox" :checked="source.monitorEnabled" @change="toggleMonitor(source)" /><span>自动</span></label><select aria-label="检测周期" :value="source.monitorIntervalMinutes" :disabled="!source.monitorEnabled || monitoringId === source.id" @change="changeInterval(source, $event.target.value)"><option :value="15">15 分钟</option><option :value="30">30 分钟</option><option :value="60">每小时</option><option :value="360">6 小时</option><option :value="1440">每日</option></select><button type="button" :disabled="checkingId !== null" @click="checkSource(source)">{{ checkingId === source.id ? '检查中…' : '立即检查' }}</button></div>
          <div class="source-schedule"><span>下次：{{ source.monitorEnabled ? formatTime(source.nextRunAt) : '未启用自动检测' }}</span><code v-if="source.lastError">{{ source.lastError }}</code></div>
        </article></div><div v-else class="empty-state"><b>还没有检测来源</b><p>先在上方登记公开文档或 GitHub  Pages 站点，雷达不会自动生成演示来源。</p></div>
      </main>

      <aside class="snapshot-panel"><div class="section-heading"><div><p class="eyebrow">SNAPSHOT LEDGER</p><h2>变更快照</h2></div><span>{{ selectedSource?.name || '未选择' }}</span></div>
        <template v-if="selectedSource"><div class="snapshot-summary"><span>{{ selectedSource.seedUrl }}</span><button type="button" :disabled="checkingId !== null" @click="checkSource(selectedSource)">检查当前来源</button></div>
          <div v-if="selectedSource.pages?.length" class="snapshot-list"><article v-for="page in selectedSource.pages" :key="page.id"><span class="change-type" :class="page.changeType.toLowerCase()">{{ changeLabel(page.changeType) }}</span><h3>{{ page.title }}</h3><a :href="page.url" target="_blank" rel="noopener noreferrer">{{ page.url }}</a><small>{{ formatTime(page.fetchedAt) }}</small><code>{{ page.contentHash }}</code><button class="diff-toggle" type="button" :disabled="diffLoadingId === page.id" @click="toggleDiff(page)">{{ diffLoadingId === page.id ? '计算中…' : diffs[page.id] ? '收起差异' : '对比上一版' }}</button><p v-if="diffErrors[page.id]" class="diff-error" role="alert">{{ diffErrors[page.id] }}</p><div v-if="diffs[page.id]" class="page-diff"><p class="diff-note">{{ diffs[page.id].note }}</p><template v-if="diffs[page.id].hasPrevious"><p v-if="diffs[page.id].fields.every(field => !field.changed)" class="diff-same">相邻快照的字段值一致。</p><details v-for="field in diffs[page.id].fields.filter(field => field.changed)" :key="field.field" class="diff-field"><summary>{{ field.label }}已变化</summary><div class="diff-values"><div><span>上一版 · #{{ diffs[page.id].previousPageId }}</span><pre>{{ field.before || '（空）' }}</pre></div><div><span>当前版 · #{{ diffs[page.id].pageId }}</span><pre>{{ field.after || '（空）' }}</pre></div></div></details><details v-if="diffs[page.id].lines.length" class="diff-lines"><summary>正文行差异（{{ diffs[page.id].lines.length }} 行）</summary><div class="line-table"><div v-for="(line, index) in diffs[page.id].lines" :key="index" :class="line.type.toLowerCase()"><span>{{ line.beforeLine || '·' }}</span><span>{{ line.afterLine || '·' }}</span><code>{{ linePrefix(line.type) }}{{ line.text }}</code></div></div></details></template></div></article></div><div v-else class="empty-state compact"><b>尚无快照</b><p>点击“立即检查”获取第一版正文与内容哈希。</p></div>
        </template><div v-else class="empty-state compact"><b>选择一个来源</b><p>查看新增、更新和未变化的正文快照。</p></div>
        <section class="radar-note"><b>检测规则</b><p>自动检测只访问你登记的同域公开来源；调度器每轮最多处理一个到期来源。网页内容仅作为资料，不作为 Agent 指令；新增和变更只进入候选审核，不会自动写入或覆盖正式知识。</p></section>
      </aside>
    </div>
  </section>
</template>

<script setup>
import { computed, onMounted, reactive, ref } from 'vue'
import { RouterLink } from 'vue-router'
import RelationGraph from '../../components/research/RelationGraph.vue'
import { radarGraph } from '../../components/research/relationGraph.js'
import { createKnowledgeCrawlSource, getKnowledgeCrawlPageDiff, getKnowledgeCrawlPages, listKnowledgeCrawlSources, listKnowledgeLibraries, runKnowledgeCrawlSource, updateKnowledgeCrawlMonitor } from '../../api/personalKnowledge.ts'

const unwrap = value => value?.data ?? value
const sources = ref([]), libraries = ref([]), selectedId = ref(null), checkingId = ref(null), monitoringId = ref(null), creating = ref(false), error = ref(''), notice = ref('')
const form = reactive({ name: '', libraryId: '', seedUrl: '', maxPages: 10, depth: 0 })
const diffs = reactive({}), diffErrors = reactive({}), diffLoadingId = ref(null)
const selectedSource = computed(() => sources.value.find(source => source.id === selectedId.value) || null)
const monitoringCount = computed(() => sources.value.filter(source => source.monitorEnabled).length)
const changedCount = computed(() => sources.value.reduce((total, source) => total + (source.pages || []).filter(page => ['ADDED', 'UPDATED'].includes(page.changeType)).length, 0))
const graph = computed(() => radarGraph(sources.value))
const activeId = computed(() => selectedId.value ? `source-${selectedId.value}` : 'radar')

function formatTime(value) { if (!value) return '尚未检查'; const date = new Date(value); return Number.isNaN(date.getTime()) ? String(value) : date.toLocaleString('zh-CN', { hour12: false }) }
function host(url) { try { return new URL(url).host } catch { return url } }
function changeLabel(value) { return ({ ADDED: '新增', UPDATED: '更新', UNCHANGED: '未变化' })[value] || value }
function statusClass(source) { return source.lastStatus === 'FAILED' ? 'failed' : source.monitorEnabled ? 'active' : 'manual' }
async function loadLibraries() { try { const result = unwrap(await listKnowledgeLibraries()); libraries.value = Array.isArray(result) ? result : result?.items || []; if (!form.libraryId && libraries.value.length) form.libraryId = libraries.value[0].id } catch (cause) { error.value = cause.message || '知识库列表读取失败' } }
async function loadSources() { try { const previous = new Map(sources.value.map(source => [source.id, source.pages || []])); const result = unwrap(await listKnowledgeCrawlSources()) || []; sources.value = result.map(source => ({ ...source, pages: previous.get(source.id) || [] })); if (selectedId.value && !sources.value.some(source => source.id === selectedId.value)) selectedId.value = null; if (!selectedId.value && sources.value.length) await selectSource(sources.value[0]) } catch (cause) { error.value = cause.message || '雷达来源读取失败' } }
async function selectSource(source) { selectedId.value = source.id; Object.keys(diffs).forEach(key => delete diffs[key]); Object.keys(diffErrors).forEach(key => delete diffErrors[key]); try { const pages = unwrap(await getKnowledgeCrawlPages(source.id, { limit: 30 })) || []; sources.value = sources.value.map(item => item.id === source.id ? { ...item, pages } : item) } catch (cause) { error.value = cause.message || '快照读取失败' } }
function selectGraphNode(node) { if (node.source) selectSource(node.source) }
async function createSource() { creating.value = true; error.value = ''; notice.value = ''; try { const result = unwrap(await createKnowledgeCrawlSource({ ...form })); form.name = ''; form.seedUrl = ''; await loadSources(); const created = sources.value.find(source => source.id === result.id); if (created) await selectSource(created); notice.value = '来源已登记，可立即检查或开启自动检测' } catch (cause) { error.value = cause.message || '来源登记失败' } finally { creating.value = false } }
async function checkSource(source) { checkingId.value = source.id; error.value = ''; notice.value = ''; try { const result = unwrap(await runKnowledgeCrawlSource(source.id)); notice.value = `检查完成：新增待审 ${result.added}，更新待审 ${result.updated}，未变化 ${result.unchanged}，失败 ${result.failed}`; await loadSources(); const current = sources.value.find(item => item.id === source.id); if (current) await selectSource(current) } catch (cause) { error.value = cause.message || '来源检查失败' } finally { checkingId.value = null } }
function linePrefix(type) { return ({ ADDED: '+ ', REMOVED: '− ', CONTEXT: '  ' })[type] || '  ' }
async function toggleDiff(page) {
  if (diffs[page.id]) { delete diffs[page.id]; return }
  diffLoadingId.value = page.id; delete diffErrors[page.id]
  try { diffs[page.id] = unwrap(await getKnowledgeCrawlPageDiff(page.id)) }
  catch (cause) { diffErrors[page.id] = cause.message || '版本差异读取失败' }
  finally { diffLoadingId.value = null }
}
async function saveMonitor(source, enabled, interval) { monitoringId.value = source.id; error.value = ''; try { const updated = unwrap(await updateKnowledgeCrawlMonitor(source.id, { enabled, intervalMinutes: Number(interval) })); sources.value = sources.value.map(item => item.id === source.id ? { ...updated, pages: item.pages || [] } : item); notice.value = enabled ? `已开启自动检测，每 ${updated.monitorIntervalMinutes} 分钟检查一次` : '已暂停自动检测，已有快照保留' } catch (cause) { error.value = cause.message || '检测设置保存失败'; await loadSources() } finally { monitoringId.value = null } }
async function toggleMonitor(source) { await saveMonitor(source, !source.monitorEnabled, source.monitorIntervalMinutes || 60) }
async function changeInterval(source, interval) { await saveMonitor(source, true, interval) }
onMounted(() => { loadLibraries(); loadSources() })
</script>

<style scoped>
