;background:var(--smart-surface);color:var(--smart-text)}button:disabled{opacity:.5;cursor:wait}.primary-action{border-color:var(--smart-primary-strong);background:var(--smart-primary-strong);color:var(--smart-bg);font-weight:600}.library-empty{color:var(--smart-muted);font-size:11px}.library-empty a{color:var(--smart-primary-strong)}.message{padding:11px 13px;margin:0 0 14px;font-size:12px}.message.error{border-left:2px solid var(--smart-danger);color:var(--smart-danger)}.message.notice{display:flex;justify-content:space-between;gap:12px;border-left:2px solid var(--smart-primary-strong);color:var(--smart-primary-strong)}.message.notice a{color:inherit;white-space:nowrap}.radar-layout{display:grid;grid-template-columns:minmax(0,1.35fr) minmax(300px,.8fr);gap:28px;margin-top:30px}.text-button{min-height:28px;padding:3px 7px;border:0;background:none;color:var(--smart-primary-strong);font-size:11px}.source-list{border-top:1px solid var(--smart-border)}.source-row{display:grid;grid-template-columns:minmax(0,1fr) auto;padding:15px 0;border-bottom:1px solid var(--smart-border)}.source-row.selected{border-bottom-color:var(--smart-primary-strong)}.source-select{min-width:0;padding:0;border:0;background:transparent;text-align:left}.source-select h3{margin:5px 0;font-size:15px;font-weight:500}.source-select p{margin:0 0 5px;color:var(--smart-muted);font-size:11px}.source-select small{color:var(--smart-muted);font:9px var(--font-mono)}.source-status{font:8px var(--font-mono);color:var(--smart-muted)}.source-status.active{color:var(--smart-primary-strong)}.source-status.failed{color:var(--smart-danger)}.source-controls{display:flex;gap:7px;align-items:start}.source-controls select{width:90px;min-height:36px;font-size:10px}.source-controls button{min-height:36px;font-size:10px}.monitor-toggle{display:flex;align-items:center;gap:5px;min-height:36px;color:var(--smart-muted);font-size:10px}.monitor-toggle input{width:14px;min-height:14px;accent-color:var(--smart-primary-strong)}.source-schedule{grid-column:1/-1;display:flex;justify-content:space-between;gap:12px;padding-top:8px;color:var(--smart-muted);font:9px var(--font-mono)}.source-schedule code{color:var(--smart-danger);overflow-wrap:anywhere}.empty-state{padding:42px 20px;border:1px dashed var(--smart-border);text-align:center;color:var(--smart-muted)}.empty-state b{color:var(--smart-text);font-weight:400}.empty-state p{margin:8px auto 0;max-width:420px;font-size:12px}.empty-state.compact{padding:28px 16px}.snapshot-summary{display:flex;justify-content:space-between;gap:10px;padding:12px 0;border-top:1px solid var(--smart-border);border-bottom:1px solid var(--smart-border)}.snapshot-summary span{min-width:0;color:var(--smart-muted);font-size:10px;overflow-wrap:anywhere}.snapshot-summary button{flex:0 0 auto;min-height:30px;font-size:10px}.snapshot-list article{padding:14px 0;border-bottom:1px solid var(--smart-border)}.snapshot-list h3{margin:6px 0;font-size:14px;font-weight:400;overflow-wrap:anywhere}.snapshot-list a{display:block;color:var(--smart-primary-strong);font-size:10px;overflow-wrap:anywhere}.snapshot-list small{display:block;margin:7px 0;color:var(--smart-muted);font:9px var(--font-mono)}.snapshot-list code{display:block;color:var(--smart-muted);font-size:8px;overflow-wrap:anywhere}.change-type{font:9px var(--font-mono);color:var(--smart-muted)}.change-type.added,.change-type.updated{color:var(--smart-warning,#d9a84e)}.diff-toggle{min-height:30px;margin-top:10px;padding:5px 9px;color:var(--smart-primary-strong);font-size:10px}.diff-error{color:var(--smart-danger);font-size:10px}.page-diff{margin-top:12px;padding-top:10px;border-top:1px solid var(--smart-border)}.diff-note,.diff-same{color:var(--smart-muted);font-size:10px;line-height:1.6}.diff-field,.diff-lines{margin-top:8px}.diff-field summary,.diff-lines summary{cursor:pointer;color:var(--smart-primary-strong);font-size:10px}.diff-values{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px;margin-top:8px}.diff-values>div{min-width:0}.diff-values span{color:var(--smart-muted);font:8px var(--font-mono)}.diff-values pre{max-height:180px;overflow:auto;padding:8px;background:color-mix(in srgb,var(--smart-surface) 70%,transparent);color:var(--smart-muted);font:9px/1.6 var(--font-mono);white-space:pre-wrap;overflow-wrap:anywhere}.line-table{max-height:320px;overflow:auto;margin-top:8px;padding:6px 0;background:color-mix(in srgb,var(--smart-surface) 65%,transparent)}.line-table>div{display:grid;grid-template-columns:28px 28px minmax(0,1fr);gap:5px;padding:2px 6px}.line-table span{color:var(--smart-muted);font:8px var(--font-mono);text-align:right}.line-table code{color:var(--smart-muted);font:9px/1.55 var(--font-mono);white-space:pre-wrap;overflow-wrap:anywhere}.line-table .removed{background:color-mix(in srgb,var(--smart-danger) 7%,transparent)}.line-table .removed code{color:var(--smart-danger)}.line-table .added{background:color-mix(in srgb,var(--smart-success,#64b99a) 7%,transparent)}.line-table .added code{color:var(--smart-success,#64b99a)}.radar-note{margin-top:22px;padding:16px;border-left:2px solid var(--smart-primary-strong);background:color-mix(in srgb,var(--smart-primary-strong) 4%,transparent)}.radar-note b{font-size:12px;font-weight:400}.radar-note p{margin:7px 0 0;color:var(--smart-muted);font-size:11px;line-height:1.7}@media(max-width:1180px){.source-registration form{grid-template-columns:1fr 1fr 1fr}.source-registration .primary-action{width:100%}}@media(max-width:900px){.radar-layout{grid-template-columns:1fr}.radar-overview{grid-template-columns:1fr 1fr}.radar-overview article:nth-child(2){border-right:0}.radar-overview article:nth-child(-n+2){border-bottom:1px solid var(--smart-border)}}@media(max-width:650px){.diff-values{grid-template-columns:1fr}.message.notice{flex-wrap:wrap}.radar-header{align-items:flex-start;flex-direction:column;padding-top:30px}.source-registration form{grid-template-columns:1fr 1fr}.name-field,.library-field,.url-field{grid-column:1/-1}.source-row{grid-template-columns:1fr}.source-controls{margin-top:12px;flex-wrap:wrap}.source-schedule{flex-direction:column}.radar-overview b{font-size:22px}}
</style>
